package com.earthtrip.notification.application.service.notification;import com.earthtrip.notification.application.port.in.NotificationUseCase;import com.earthtrip.notification.application.port.out.*;import com.earthtrip.sharedkernel.error.EarthTripException;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional class NotificationService implements NotificationUseCase{private final NotificationStorePort store;private final PushTokenProtectorPort protector;private final Clock clock;NotificationService(NotificationStorePort s,PushTokenProtectorPort p,Clock c){store=s;protector=p;clock=c;}@Override @Transactional(readOnly=true)public List<NotificationResult>list(UUID user,boolean unread){return store.list(user).stream().filter(n->!unread||n.readAt()==null).map(NotificationService::result).toList();}@Override public void markRead(UUID user,UUID id,boolean read){NotificationStorePort.NotificationRecord n=load(user,id);store.save(copy(n,read?clock.instant():null,n.hiddenAt()));}@Override public void markManyRead(UUID user,List<UUID>ids){if(ids==null||ids.size()>200)throw EarthTripException.badRequest("INVALID_NOTIFICATION_BATCH","한 번에 최대 200개까지 처리할 수 있습니다.");ids.forEach(id->markRead(user,id,true));}@Override public void hide(UUID user,UUID id){NotificationStorePort.NotificationRecord n=load(user,id);store.save(copy(n,n.readAt(),clock.instant()));}@Override @Transactional(readOnly=true)public SummaryResult summary(UUID user){List<NotificationStorePort.NotificationRecord>unread=store.list(user).stream().filter(n->n.readAt()==null).toList();Map<UUID,Long>byTrip=new LinkedHashMap<>();Map<String,Long>byType=new LinkedHashMap<>();unread.forEach(n->{if(n.tripId()!=null)byTrip.merge(n.tripId(),1L,Long::sum);byType.merge(n.type(),1L,Long::sum);});return new SummaryResult(unread.size(),Map.copyOf(byTrip),Map.copyOf(byType));}@Override public PreferenceResult preferences(UUID user){return result(loadOrCreatePreference(user));}@Override public PreferenceResult updatePreferences(UUID user,PreferenceCommand c){NotificationStorePort.PreferenceRecord old=loadOrCreatePreference(user);LocalTime start=c.quietStart()==null?old.quietStart():c.quietStart();LocalTime end=c.quietEnd()==null?old.quietEnd():c.quietEnd();String zone=c.quietTimeZone()==null?old.quietTimeZone():ZoneId.of(c.quietTimeZone()).getId();if((start==null)!=(end==null))throw EarthTripException.badRequest("INVALID_QUIET_HOURS","조용한 시간 시작과 종료를 함께 입력해 주세요.");return result(store.savePreference(new NotificationStorePort.PreferenceRecord(user,value(c.mentionsEnabled(),old.mentions()),value(c.scheduleEnabled(),old.schedule()),value(c.expenseEnabled(),old.expense()),value(c.invitationEnabled(),old.invitation()),value(c.pushEnabled(),old.push()),value(c.emailEnabled(),old.email()),start,end,zone,old.version(),clock.instant())));}@Override public void registerDevice(UUID user,String deviceId,String platform,String token,int appBuild){if(deviceId==null||deviceId.isBlank()||deviceId.length()>100||appBuild<1)throw EarthTripException.badRequest("INVALID_PUSH_DEVICE","푸시 기기 정보를 확인해 주세요.");String normalized=platform.strip().toUpperCase(Locale.ROOT);if(!Set.of("IOS","ANDROID").contains(normalized))throw EarthTripException.badRequest("INVALID_PUSH_PLATFORM","플랫폼은 IOS 또는 ANDROID여야 합니다.");PushTokenProtectorPort.ProtectedToken protectedToken=protector.protect(token);Instant now=clock.instant();NotificationStorePort.DeviceRecord old=store.device(deviceId).orElse(null);if(old!=null&&old.active()&&!old.userId().equals(user))throw EarthTripException.conflict("PUSH_DEVICE_OWNED_BY_OTHER_ACCOUNT","다른 로그인 계정에서 사용 중인 기기입니다.");Instant createdAt=old==null||!old.userId().equals(user)?now:old.createdAt();store.saveDevice(new NotificationStorePort.DeviceRecord(deviceId,user,normalized,protectedToken.hash(),protectedToken.cipher(),appBuild,true,createdAt,now));}@Override public void removeDevice(UUID user,String deviceId){NotificationStorePort.DeviceRecord old=store.device(deviceId).filter(d->d.userId().equals(user)).orElseThrow(()->EarthTripException.notFound("PUSH_DEVICE_NOT_FOUND","푸시 기기를 찾을 수 없습니다."));store.saveDevice(new NotificationStorePort.DeviceRecord(old.deviceId(),old.userId(),old.platform(),old.tokenHash(),old.tokenCipher(),old.appBuild(),false,old.createdAt(),clock.instant()));}private NotificationStorePort.NotificationRecord load(UUID user,UUID id){return store.find(id).filter(n->n.userId().equals(user)&&n.hiddenAt()==null).orElseThrow(()->EarthTripException.notFound("NOTIFICATION_NOT_FOUND","알림을 찾을 수 없습니다."));}private NotificationStorePort.PreferenceRecord loadOrCreatePreference(UUID user){return store.preference(user).orElseGet(()->store.savePreference(new NotificationStorePort.PreferenceRecord(user,true,true,true,true,true,false,null,null,"Asia/Seoul",0,clock.instant())));}private static boolean value(Boolean v,boolean fallback){return v==null?fallback:v;}private static NotificationStorePort.NotificationRecord copy(NotificationStorePort.NotificationRecord n,Instant read,Instant hidden){return new NotificationStorePort.NotificationRecord(n.id(),n.userId(),n.tripId(),n.type(),n.title(),n.body(),n.deepLink(),n.metadata(),n.createdAt(),read,hidden,n.version());}private static NotificationResult result(NotificationStorePort.NotificationRecord n){return new NotificationResult(n.id(),n.tripId(),n.type(),n.title(),n.body(),n.deepLink(),n.metadata(),n.createdAt(),n.readAt(),n.version());}private static PreferenceResult result(NotificationStorePort.PreferenceRecord p){return new PreferenceResult(p.mentions(),p.schedule(),p.expense(),p.invitation(),p.push(),p.email(),p.quietStart(),p.quietEnd(),p.quietTimeZone(),p.version(),p.updatedAt());}}
